import {esc} from './care-site.js';
const options=(values,current)=>values.map(v=>`<option ${v===current?'selected':''}>${esc(v)}</option>`).join('');
export function providerList(providers){return `<div class="admin-header"><div><h1>Your providers</h1><p>Only verified, published profiles appear in the directory.</p></div><a class="btn" href="/admin/providers/new">Add provider</a></div>${providers.length?`<div class="table-wrap"><table class="post-table"><thead><tr><th>Name</th><th>Profession</th><th>City</th><th>Status</th><th>Action</th></tr></thead><tbody>${providers.map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(p.profession)}</td><td>${esc(p.city)}</td><td>${p.active?'Published':p.verified?'Verified · hidden':'Needs verification'}</td><td><a class="text-link" href="/admin/providers/${p.id}">Edit profile</a></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><h2>Your directory starts here.</h2><p>Add your clinicians, check their credentials, then publish their profiles.</p></div>'}`;}
export function providerEditor(provider){const p=provider||{};return `<div class="admin-header"><div><a class="text-link" href="/admin/providers">← All providers</a><h1>${p.id?'Edit provider':'Add a provider'}</h1></div></div><form id="provider-form" class="form" data-id="${esc(p.id||'')}"><div class="pair"><label>Full name<input name="name" required minlength="2" maxlength="100" value="${esc(p.name)}"></label><label>Profile URL slug<input name="slug" required maxlength="150" pattern="[a-z0-9]+(?:-[a-z0-9]+)*" value="${esc(p.slug)}" placeholder="firstname-lastname"></label></div><div class="pair"><label>Profession<select name="profession">${options(['Therapist','Clinical psychologist','Psychiatrist','Counsellor'],p.profession)}</select></label><label>Qualifications<input name="credentials" required minlength="2" maxlength="200" value="${esc(p.credentials)}"></label></div><label>Professional registration<input name="registration" maxlength="150" value="${esc(p.registration)}"><span class="small">Required before publishing psychiatrists and clinical psychologists.</span></label><div class="pair"><label>City<input name="city" required minlength="2" maxlength="100" value="${esc(p.city)}"></label><label>Languages, separated by commas<input name="languages" required maxlength="600" value="${esc((p.languages||['English']).join(', '))}"></label></div><label>Areas of focus, separated by commas<input name="specialties" maxlength="1000" value="${esc((p.specialties||[]).join(', '))}"></label><label>Session formats<select name="modes">${options(['Online','In person','Online and in person'],p.modes?.length===2?'Online and in person':p.modes?.[0])}</select></label><label>About this provider<textarea name="bio" required minlength="20" maxlength="3000">${esc(p.bio)}</textarea></label><label class="check-label"><input type="checkbox" name="verified" ${p.verified?'checked':''}> I have checked this provider’s identity, qualifications, registration where applicable, and permission to publish this profile.</label><label class="check-label"><input type="checkbox" name="active" ${p.active?'checked':''}> Publish this verified profile in the public directory.</label><button class="btn" type="submit">Save provider</button><p id="provider-state" role="status">Uncheck Publish to remove a provider from public view.</p></form>`;}
export function requestList(requests){return `<div class="admin-header"><div><h1>Care enquiries</h1><p>Testing mode · No automatic emails or appointments.</p></div><button class="btn light" data-action="refresh-care">Refresh</button></div><label class="form">Filter by status<select id="request-status-filter">${options(['All','new','reviewing','contacted','closed'],'All')}</select></label><div id="request-results">${requestRows(requests)}</div>`;}
export function requestRows(requests,status='All'){const found=requests.filter(r=>status==='All'||r.status===status);return found.length?found.map(r=>`<details class="enquiry-row"><summary><span><strong>${esc(r.contact_name)}</strong><small>${esc(r.kind.replaceAll('_',' '))} · ${esc(r.service)} · ${esc(r.city)}</small></span><span class="status">${esc(r.status)}</span><time>${new Date(r.created_at).toLocaleDateString('en-IN')}</time></summary><div class="enquiry-details"><dl class="review-list"><dt>Email</dt><dd>${esc(r.email)}</dd><dt>Phone</dt><dd>${esc(r.phone||'Not provided')}</dd><dt>Preferences</dt><dd>${esc(r.language)} · ${esc(r.mode)}</dd><dt>Enquiring as</dt><dd>${esc(r.relationship)}</dd>${r.provider_id?`<dt>Provider reference</dt><dd>${esc(r.provider_id)}</dd>`:''}${r.professional_details?`<dt>Professional details</dt><dd class="preserve-lines">${esc(r.professional_details)}</dd>`:''}<dt>Consent</dt><dd>Agreed to test enquiry storage</dd></dl><form class="form request-status-form" data-id="${esc(r.id)}"><label>Review status<select name="status">${options(['new','reviewing','contacted','closed'],r.status)}</select></label><button class="btn light" type="submit">Save status</button><p role="status"></p></form></div></details>`).join(''):'<div class="empty"><h2>No enquiries here.</h2><p>Test submissions will appear here for your review.</p></div>';}
